import json, sqlite3, pathlib, sys, urllib.parse
root=pathlib.Path(sys.argv[1]); records=json.loads((root/'database-backups.json').read_text()); checked=[]
for record in records:
    source=sqlite3.connect('file:'+urllib.parse.quote(record['path'],safe='/')+'?mode=ro',uri=True,timeout=30)
    if source.execute('PRAGMA integrity_check').fetchall() != [('ok',)]: raise RuntimeError('live database integrity failed')
    for table, prior in record['primary_keys'].items():
        current={r[0] for r in source.execute('SELECT id FROM "'+table+'"')}
        if not set(prior).issubset(current): raise RuntimeError('retained identifiers missing')
    checked.append({'path':record['path'],'integrity':'ok','retained_primary_keys_preserved':True});source.close()
(root/'database-after.json').write_text(json.dumps(checked,indent=2)+'\n')
print(json.dumps({'databases':len(checked),'integrity':'ok','retained_primary_keys_preserved':True}))
